def calculate_kelly_size(csv_path, symbol_filter, bankroll):
    df = pd.read_csv(csv_path)
    btc_trades = df[df['symbol'] == symbol_filter]

    if len(btc_trades) == 0:
        return {"fraction": 0.0, "amount": 0.0}

    win_rate = (btc_trades['realized_pnl'] > 0).mean()

    positive_pnls = btc_trades[btc_trades['realized_pnl'] > 0]['realized_pnl']
    negative_pnls = btc_trades[btc_trades['realized_pnl'] <= 0]['realized_pnl']

    if len(positive_pnls) == 0 or len(negative_pnls) == 0:
        return {"fraction": 0.0, "amount": 0.0}

    avg_win = positive_pnls.mean()
    avg_loss = abs(negative_pnls.mean())
    payoff_ratio = avg_win / avg_loss

    kelly_fraction = (win_rate * payoff_ratio - (1 - win_rate)) / payoff_ratio
    kelly_amount = kelly_fraction * bankroll

    return {"fraction": kelly_fraction, "amount": kelly_amount}

